# vm — a register-machine bytecode interpreter: the core loop every VM / DSL / calculator
# runs (fetch → decode → dispatch → execute over a register file). A deterministic instruction
# stream is generated by the shared LCG and executed in order; the final register state reduces
# to a checksum. A real interpreter workload — dispatch-heavy, not a teaching algorithm — and
# byte-identical across every language.
import std/os
import std/strutils

const MOD: int64 = 1000000007
const NREG = 8

proc main() =
  if paramCount() < 1:
    stderr.writeLine("usage: vm <n>")
    quit(1)
  let n = parseBiggestInt(paramStr(1)).int64
  var seed: int64 = 42
  var regs: array[NREG, int64]
  for i in 0 ..< NREG:                                        # seed the register file
    regs[i] = int64(i) + 1
  for k in 0'i64 ..< n:
    seed = (seed * 1103515245 + 12345) mod 2147483648'i64     # fetch
    let instr = (seed shr 8) and 0x7fffff                     # decode
    let op = instr mod 8
    let dst = (instr div 8) mod NREG
    let a = (instr div 64) mod NREG
    let imm = (instr div 512) mod 251
    case op                                                   # dispatch → execute
    of 0: regs[dst] = imm                                     # LOADI
    of 1: regs[dst] = (regs[dst] + regs[a]) mod MOD           # ADD
    of 2: regs[dst] = (regs[dst] + MOD - regs[a]) mod MOD     # SUB
    of 3: regs[dst] = (regs[dst] * regs[a] + 1) mod MOD       # MULADD
    of 4: regs[dst] = (regs[dst] + imm) mod MOD               # ADDI
    of 5: regs[dst] = (regs[dst] * (imm + 1)) mod MOD         # MULI
    of 6: regs[dst] = regs[a]                                 # MOV
    else: regs[dst] = (regs[dst] + regs[a] + imm) mod MOD     # MIX
  var checksum: int64 = 0
  for i in 0 ..< NREG:
    checksum = (checksum * 31 + regs[i]) and 268435455
  echo checksum

main()
